"use client"

import * as React from "react"
import Link from "next/link"
import { ArrowLeftIcon } from "lucide-react"

import { LivepeerLogo } from "@/components/brand"
import { getLivepeerOrgFoundationHref } from "@/components/livepeer-ui/livepeer-org-header-nav"
import { MobileNavigationMenu } from "@/components/livepeer-ui/mobile-navigation-menu"
import type { LivepeerOrgSite } from "@/components/livepeer-ui/contracts"

const loginLinks = [
  { label: "Forum", href: "https://forum.livepeer.org" },
  {
    label: "Orchestrator",
    href: "https://explorer.livepeer.org/orchestrators",
  },
  { label: "Agent Console", href: "/mockups/livepeer-agent" },
] as const

export function LivepeerOrgMenu({ site }: { site: LivepeerOrgSite }) {
  const [open, setOpen] = React.useState(false)
  const [showLoginLinks, setShowLoginLinks] = React.useState(false)
  const resetLoginLinksTimer = React.useRef<ReturnType<
    typeof setTimeout
  > | null>(null)
  const allLinks = [
    ...site.menuLinks,
    ...site.footerGroups.flatMap((group) => group.links),
  ]
  const findHref = (labels: string[], path: string, fallback: string) =>
    site.menuLinks.find(
      (link) => labels.includes(link.label) || link.href.includes(path)
    )?.href ??
    allLinks.find(
      (link) => labels.includes(link.label) || link.href.includes(path)
    )?.href ??
    fallback
  const mobileLinks = [
    { label: "Home", href: site.homeHref },
    { label: "Foundation", href: getLivepeerOrgFoundationHref(site) },
    {
      label: "Ecosystem",
      href: findHref(["Ecosystem"], "/ecosystem", `${site.homeHref}/ecosystem`),
    },
    {
      label: "Agent",
      href: findHref(
        ["Livepeer Agent", "Agent"],
        "/agent",
        `${site.homeHref}/agent`
      ),
    },
    {
      label: "$LPT",
      href: findHref(
        ["Livepeer Token", "$LPT"],
        "/token",
        `${site.homeHref}/token`
      ),
    },
    {
      label: "Provide Compute",
      href: findHref(
        ["GPU", "Provide GPUs", "Provide GPU", "Provide Compute"],
        "/compute",
        `${site.homeHref}/compute`
      ).replace(/\/earn(?=\/|$)/, "/compute"),
    },
    {
      label: "Latest Updates",
      href: findHref(
        ["Blog", "Latest Updates"],
        "/latest",
        `${site.homeHref}/latest`
      ).replace(/\/blog(?=\/|$)/, "/latest"),
    },
  ]

  const clearLoginLinksReset = React.useCallback(() => {
    if (resetLoginLinksTimer.current) {
      clearTimeout(resetLoginLinksTimer.current)
      resetLoginLinksTimer.current = null
    }
  }, [])

  React.useEffect(() => clearLoginLinksReset, [clearLoginLinksReset])

  const handleOpenChange = (nextOpen: boolean) => {
    clearLoginLinksReset()
    setOpen(nextOpen)
    if (!nextOpen) {
      resetLoginLinksTimer.current = setTimeout(() => {
        setShowLoginLinks(false)
        resetLoginLinksTimer.current = null
      }, 220)
    }
  }

  return (
    <MobileNavigationMenu
      title="site navigation"
      open={open}
      onOpenChange={handleOpenChange}
      header={
        <Link href={site.homeHref} aria-label="Livepeer.org home">
          <LivepeerLogo />
        </Link>
      }
    >
      {(close) => (
        <div className="min-h-0 flex-1 overflow-y-auto px-4 pt-6 pb-6 sm:px-6 sm:pt-8 sm:pb-8">
          <nav
            className="relative -left-[0.04em] flex flex-col"
            aria-label="Mobile site sections"
          >
            {showLoginLinks ? (
              <>
                <button
                  type="button"
                  onClick={() => setShowLoginLinks(false)}
                  className="mb-6 flex w-fit items-center gap-2 rounded-sm py-2 font-sans text-sm text-muted-foreground transition-colors outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <ArrowLeftIcon aria-hidden="true" className="size-4" />
                  Back
                </button>
                {loginLinks.map((item) => {
                  const className =
                    "flex items-center gap-2 rounded-sm py-2.5 font-display text-display-sm text-foreground outline-none transition-colors hover:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring sm:text-display-lg"
                  const content = (
                    <>
                      <span>{item.label}</span>
                      <span aria-hidden="true">↗</span>
                    </>
                  )

                  return item.href.startsWith("http") ? (
                    <a
                      key={item.label}
                      href={item.href}
                      target="_blank"
                      rel="noreferrer"
                      onClick={close}
                      className={className}
                    >
                      {content}
                    </a>
                  ) : (
                    <Link
                      key={item.label}
                      href={item.href}
                      onClick={close}
                      className={className}
                    >
                      {content}
                    </Link>
                  )
                })}
              </>
            ) : (
              <>
                {mobileLinks.map((item) => {
                  const className =
                    "rounded-sm py-2.5 font-display text-display-sm text-foreground transition-colors outline-none hover:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring sm:text-display-lg"

                  return item.href.startsWith("http") ? (
                    <a
                      key={item.label}
                      href={item.href}
                      target="_blank"
                      rel="noreferrer"
                      onClick={close}
                      className={className}
                    >
                      {item.label}
                    </a>
                  ) : (
                    <Link
                      key={item.label}
                      href={item.href}
                      onClick={close}
                      className={className}
                    >
                      {item.label}
                    </Link>
                  )
                })}
                <button
                  type="button"
                  onClick={() => setShowLoginLinks(true)}
                  className="mt-8 flex items-center gap-2 rounded-sm py-2.5 font-display text-display-sm text-foreground transition-colors outline-none hover:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring sm:text-display-lg"
                >
                  <span>Login</span>
                  <span aria-hidden="true">→</span>
                </button>
              </>
            )}
          </nav>
        </div>
      )}
    </MobileNavigationMenu>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  Sheet,
  SheetContent,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet"

function MobileMenuIcon({ open = false }: { open?: boolean }) {
  return (
    <span aria-hidden="true" className="relative block h-4 w-8">
      <span
        className="absolute right-0.5 h-1 w-[30px] transition-[top,transform] duration-[250ms] ease-[cubic-bezier(0.4,0,0.2,1)] motion-reduce:transition-none"
        style={{
          top: open ? 6 : 2,
          transform: open ? "rotate(135deg)" : "rotate(0deg)",
          transformOrigin: "19px 50%",
        }}
      >
        <span
          className="block h-full w-full origin-right bg-current transition-transform duration-[250ms] ease-[cubic-bezier(0.4,0,0.2,1)] motion-reduce:transition-none"
          style={{ transform: open ? "scaleX(0.733333)" : "scaleX(1)" }}
        />
      </span>
      <span
        className="absolute right-0.5 h-1 w-[22px] origin-center bg-current transition-[top,transform] duration-[250ms] ease-[cubic-bezier(0.4,0,0.2,1)] motion-reduce:transition-none"
        style={{
          top: open ? 6 : 10,
          transform: open ? "rotate(45deg)" : "rotate(0deg)",
        }}
      />
    </span>
  )
}

export function MobileNavigationMenu({
  title,
  header,
  children,
  open,
  onOpenChange,
}: {
  title: string
  header: React.ReactNode
  children: (close: () => void) => React.ReactNode
  open: boolean
  onOpenChange: (open: boolean) => void
}) {
  const close = React.useCallback(() => onOpenChange(false), [onOpenChange])

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetTrigger
        render={
          <Button
            variant="ghost"
            size="icon-sm"
            className="hover:bg-transparent hover:text-foreground aria-expanded:bg-transparent dark:hover:bg-transparent"
          />
        }
      >
        <MobileMenuIcon open={open} />
        <span className="sr-only">
          {open ? `Close ${title}` : `Open ${title}`}
        </span>
      </SheetTrigger>
      <SheetContent
        side="top"
        showCloseButton={false}
        overlayClassName="bg-transparent transition-none supports-backdrop-filter:backdrop-blur-none"
        className="z-[70] h-dvh max-h-none w-screen max-w-none overflow-hidden border-0 bg-background p-0 text-foreground opacity-100 shadow-none transition-opacity duration-200 ease-out data-ending-style:opacity-0 data-starting-style:opacity-0 data-[side=top]:h-dvh data-[side=top]:border-b-0 data-[side=top]:data-ending-style:translate-y-0 data-[side=top]:data-starting-style:translate-y-0 motion-reduce:transition-none"
      >
        <SheetTitle className="sr-only">{title}</SheetTitle>
        <div className="flex h-dvh flex-col">
          <div className="flex h-16 shrink-0 items-center justify-between px-4 sm:px-6">
            {header}
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              aria-label={`Close ${title}`}
              onClick={close}
              className="hover:bg-transparent dark:hover:bg-transparent"
            >
              <MobileMenuIcon open />
            </Button>
          </div>
          {children(close)}
        </div>
      </SheetContent>
    </Sheet>
  )
}

