  return (
    <span
      className={[
        "inline-flex shrink-0 items-center gap-1.5 text-foreground",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
      {...props}
    >
      {/* <LivepeerGradientSymbol className="h-4 w-auto" aria-hidden="true" /> */}
      <LivepeerWordmark className="h-4 w-auto" aria-hidden="true" />
